  const colors = Object.entries(v.applied_tokens || vctx?.tokens || {}).filter(([, val]) => /^#[0-9a-f]{3,8}$/i.test(String(val)));
  const prop = (k, val) => `<div class="prop"><span>${k}</span><span>${val}</span></div>`;
  const design = `<div class="inspect-block"><div class="insp-layer">${icon('frame', 14)}<div><strong>${esc(screenTitle)}</strong><div class="tiny muted">${esc(v.runner_name)} · v${v.version}</div></div></div>${badge(label, kind)}</div>
   <div class="inspect-block"><h3>Frame</h3>${prop('Width', '720') + prop('Height', '960') + prop('Version', 'v' + v.version) + prop('Context', `<span class="mono">v${vctx?.version || '?'} · ${fmtHash(vctx?.hash)}</span>`)}</div>
   ${colors.length ? `<div class="inspect-block"><h3>Fill · tokens${v.applied_tokens ? ' applied' : ''}</h3>${colors.map(([k, val]) => `<div class="fillrow"><span class="swatch" style="background:${esc(val)}"></span><span>${esc(k)}</span><span class="mono">${esc(String(val).toUpperCase())}</span></div>`).join('')}</div>` : ''}
   ${(v.references || []).length ? `<div class="inspect-block"><h3>Reference images</h3><div class="refstrip">${v.references.map(r => `<button class="refthumb" data-ref-open="${esc(v.job_id)}:${esc(r.file)}:${esc(r.name)}" title="${esc(r.name)}${r.note ? ' · ' + esc(r.note) : ''}"><img src="${jobRefUrl(v.job_id, r)}" alt="${esc(r.name)}"></button>`).join('')}</div><p class="tiny muted">Passed to the agent with the brief. Whether they were applied needs your review.</p></div>` : ''}
   <div class="inspect-block"><h3>Lineage</h3>${(v.mix_sources || []).length ? `<p class="tiny muted" style="margin:0 0 8px">Mixed from:</p>${v.mix_sources.map(m => `<div class="prop"><span>${esc(b.screens[Number(m.screen)])}</span><span>${esc(m.name)} v${m.version}</span></div>`).join('')}` : ''}${parent ? `<button class="tiny" data-parent="${parent.id}">${icon('back', 12)} View parent v${parent.version}</button>` : `<p class="tiny muted">${v.kind === 'mix' ? 'Composed from existing versions.' : 'Original generation.'}</p>`}${children.length ? `<div class="tiny muted" style="margin-top:8px">Revised in: ${children.map(c => `<a href="${boardPath(b, 'review', c.id)}">v${c.version}</a>`).join(', ')}</div>` : ''}${v.review_state === 'pending' ? `<div class="decision"><p class="tiny">This revision awaits your decision. The parent is untouched either way.</p><div class="row"><button class="primary" data-accept="${v.id}">${icon('check', 13)} Accept revision</button><button data-revert="${v.id}">${icon('undo', 13)} Revert</button></div></div>` : ''}</div>
   ${v.changes.length ? `<div class="inspect-block"><h3>Changes in this version</h3>${v.changes.map(c => `<p>${esc(c)}</p>`).join('')}</div>` : ''}`;
  const checksTab = `<div class="inspect-block"><p class="tiny muted" style="margin:0 0 6px">Deterministic checks show evidence only. They do not certify accessibility, brand or visual quality.</p>${['pass', 'fail', 'not_assessable', 'review'].map(group).join('')}</div>`;
  const commentsTab = `<div class="inspect-block"><div class="row between"><h3 style="margin:0">Comments</h3>${badge(`${chosen.length}/${open.length} selected`)}</div>${annotations.map((a, i) => `<div class="pinrow ${S.activePin === a.id ? 'focus' : ''}"><label class="row" style="margin:0;align-items:flex-start">${a.status === 'applied' ? `<span class="chip">${i + 1}</span>` : `<input type="checkbox" data-pin-select="${a.id}" ${a.selected !== false ? 'checked' : ''} aria-label="Include pin ${i + 1} in revision">`}<span style="flex:1"><button class="linklike" data-pin-focus="${a.id}" data-pin-screen="${a.screen}">${esc(a.comment)}</button><small class="tiny muted">${esc(b.screens[Number(a.screen)])}${a.element_id ? ` · region “${esc(a.element_id)}”` : ' · whole screen (no element anchor)'}${a.status === 'applied' ? ' · applied in a revision' : ''}</small></span></label>${a.status === 'applied' ? '' : `<span class="row" style="gap:2px"><button class="ghost tiny" data-pin-edit="${a.id}" aria-label="Edit pin ${i + 1}">${icon('edit', 13)}</button><button class="ghost tiny" data-pin-delete="${a.id}" aria-label="Delete pin ${i + 1}">${icon('trash', 13)}</button></span>`}</div>`).join('') || '<p>No comments yet. Open Review, pick the comment tool and click a screen.</p>'}<button class="tiny" data-action="review">${icon('plus', 12)} Add comment</button></div>`;
